export class MarkdownRegionBoundsError extends RangeError {
    constructor() {
        super('Invalid projection region offsets.');
        this.name = 'MarkdownRegionBoundsError';
    }
}
export function spliceMarkdownRegion(current, region, replacement) {
    if (!Number.isInteger(region.start) ||
        !Number.isInteger(region.end) ||
        region.start < 0 ||
        region.end < region.start ||
        region.end > current.length) {
        throw new MarkdownRegionBoundsError();
    }
    return (current.slice(0, region.start) + replacement + current.slice(region.end));
}
/** Re-locate the candidate; locator failures belong to the caller's format. */
export function hasExactMarkdownRegion(current, expected, locate) {
    const region = locate(current);
    return Boolean(region && current.slice(region.start, region.end) === expected);
}
export function markdownLines(markdown) {
    const lines = [];
    let fence;
    for (const { start, text, raw } of sourceLines(markdown)) {
        if (fence) {
            const closing = isClosingFence(text, fence);
            lines.push({ start, text, raw, fenced: true });
            if (closing) {
                fence = undefined;
            }
            continue;
        }
        const openingFence = parseOpeningFence(text);
        if (openingFence) {
            fence = openingFence;
            lines.push({ start, text, raw, fenced: true });
            continue;
        }
        lines.push({ start, text, raw, fenced: false });
    }
    return lines;
}
export function markdownHeadings(markdown) {
    const headings = [];
    let fence;
    for (const { start, text: line } of sourceLines(markdown)) {
        if (fence) {
            if (isClosingFence(line, fence)) {
                fence = undefined;
            }
            continue;
        }
        const openingFence = parseOpeningFence(line);
        if (openingFence) {
            fence = openingFence;
            continue;
        }
        const heading = /^ {0,3}(#{1,6})(?:[\t ]+|$)(.*)$/.exec(line);
        if (heading) {
            const text = heading[2].replace(/[\t ]+#+[\t ]*$/, '').trimEnd();
            headings.push({
                start,
                level: heading[1].length,
                canonical: `${heading[1]}${text ? ` ${text}` : ''}`,
            });
        }
    }
    return headings;
}
function sourceLines(markdown) {
    const lines = [];
    let start = 0;
    while (start < markdown.length) {
        const newline = markdown.indexOf('\n', start);
        if (newline === -1) {
            lines.push({
                start,
                text: markdown.slice(start),
                raw: markdown.slice(start),
            });
            break;
        }
        const raw = markdown.slice(start, newline + 1);
        const endingLength = newline > start && markdown[newline - 1] === '\r' ? 2 : 1;
        lines.push({
            start,
            text: markdown.slice(start, newline + 1 - endingLength),
            raw,
        });
        start = newline + 1;
    }
    return lines;
}
function parseOpeningFence(line) {
    const match = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!match) {
        return undefined;
    }
    const marker = match[1][0];
    if (marker === '`' && match[2].includes('`')) {
        return undefined;
    }
    return { marker, length: match[1].length };
}
function isClosingFence(line, fence) {
    const match = /^ {0,3}(`+|~+)[\t ]*$/.exec(line);
    return Boolean(match && match[1][0] === fence.marker && match[1].length >= fence.length);
}
